string S[] = {"in", "ft", "yd", "mi"};
int L[] = {1760*3*12,1760*3,1760,1};
class LengthUnitCalculator {
public:
	double calc(int amount, string fromUnit, string toUnit) {
		int X,Y;
    for(int i=0;i<4;i++){
      if(fromUnit == S[i])
        X = i;
      if(toUnit == S[i])
        Y = i;
    }
    double XX,YY;
    XX = 1.0/(double)L[X];
    YY = 1.0/(double)L[Y];
    double Ans = amount * (XX/(double)YY);
    return Ans;
	}
};


